# Auto-fetch custom_sales_person, custom_technician & custom_technician_name on Delivery Note Save
for item in doc.get("items", []):
    if item.get("so_detail"):
        so_item = frappe.db.get_value("Sales Order Item", item.so_detail, ["custom_sales_person", "custom_technician", "custom_technician_name"], as_dict=True)
        if so_item:
            if not item.get("custom_sales_person") and so_item.get("custom_sales_person"):
                item.custom_sales_person = so_item.custom_sales_person
            if not item.get("custom_technician") and so_item.get("custom_technician"):
                item.custom_technician = so_item.custom_technician
            if not item.get("custom_technician_name") and so_item.get("custom_technician_name"):
                item.custom_technician_name = so_item.custom_technician_name

    if item.get("custom_technician") and not item.get("custom_technician_name"):
        emp_name = frappe.db.get_value("Employee", item.custom_technician, "employee_name")
        if emp_name:
            item.custom_technician_name = emp_name
